-- oracle: pub400
-- JSON_OBJECT, JSON_ARRAY and their formatting.
SELECT JSON_OBJECT('a' VALUE 1, 'b' VALUE 'x') FROM SYSIBM.SYSDUMMY1;
SELECT JSON_OBJECT(KEY 'a' VALUE 1.50, KEY 'b' VALUE -0.5, KEY 'c' VALUE 1.5E0, KEY 'd' VALUE CAST(1 AS SMALLINT), KEY 'e' VALUE DECFLOAT('1.0E3')) FROM SYSIBM.SYSDUMMY1;
SELECT JSON_OBJECT('a' VALUE NULL), JSON_OBJECT('a' VALUE NULL ABSENT ON NULL), JSON_OBJECT('a' VALUE NULL NULL ON NULL) FROM SYSIBM.SYSDUMMY1;
SELECT JSON_OBJECT('q' VALUE 'he said "hi" \ / ' || X'25' || X'05' || 'é€') FROM SYSIBM.SYSDUMMY1;
SELECT JSON_OBJECT('a' VALUE '{"x":1}' FORMAT JSON, 'b' VALUE '{"x":1}') FROM SYSIBM.SYSDUMMY1;
SELECT JSON_OBJECT('a' VALUE JSON_ARRAY(1, 2, 'x'), 'b' VALUE JSON_OBJECT('c' VALUE TRUE)) FROM SYSIBM.SYSDUMMY1;
SELECT JSON_OBJECT('d' VALUE DATE('2026-11-05'), 't' VALUE TIME('10:20:30'), 's' VALUE TIMESTAMP('2026-11-05-10.20.30.123456'), 'x' VALUE BX'C1F0') FROM SYSIBM.SYSDUMMY1;
SELECT JSON_OBJECT('a' VALUE 1, 'a' VALUE 2) FROM SYSIBM.SYSDUMMY1;
SELECT JSON_OBJECT('a' VALUE 1, 'a' VALUE 2 WITH UNIQUE KEYS) FROM SYSIBM.SYSDUMMY1;
SELECT JSON_OBJECT() FROM SYSIBM.SYSDUMMY1;
SELECT JSON_OBJECT('a' VALUE 1 RETURNING VARCHAR(5)) FROM SYSIBM.SYSDUMMY1;
SELECT JSON_OBJECT('a' VALUE 'abcdef' RETURNING VARCHAR(5)) FROM SYSIBM.SYSDUMMY1;
SELECT JSON_ARRAY(1, NULL, 'a'), JSON_ARRAY(1, NULL, 'a' NULL ON NULL), JSON_ARRAY(), JSON_ARRAY('[1,2]' FORMAT JSON) FROM SYSIBM.SYSDUMMY1;
SELECT JSON_ARRAY(VALUES 1 UNION ALL VALUES 2) FROM SYSIBM.SYSDUMMY1;
SELECT JSON_ARRAY(1E300, -0E0, 0.1E0, CAST(0.1 AS REAL), 12345678901234567890) FROM SYSIBM.SYSDUMMY1;
SELECT JSON_ARRAY(TRUE, FALSE, 1 = 1) FROM SYSIBM.SYSDUMMY1;
SELECT JSON_OBJECT('a' VALUE '[1,2' FORMAT JSON) FROM SYSIBM.SYSDUMMY1;
SELECT JSON_VALUE('{"a":{"b":[10,20,30]},"s":"xéy","n":null,"t":true,"f":1.5e2}', '$.a.b[1]'), JSON_VALUE('{"a":"xyz"}', '$.a'), JSON_VALUE('{"a":1.5}', '$.a' RETURNING DECIMAL(5, 2)), JSON_VALUE('{"a":1.5}', '$.a' RETURNING INTEGER) FROM SYSIBM.SYSDUMMY1;
SELECT JSON_VALUE('{"s":"xéy"}', '$.s'), JSON_VALUE('{"n":null}', '$.n'), JSON_VALUE('{"t":true}', '$.t'), JSON_VALUE('{"f":1.5e2}', '$.f'), JSON_VALUE('{"f":1.5e2}', '$.f' RETURNING DOUBLE) FROM SYSIBM.SYSDUMMY1;
SELECT JSON_VALUE('{"a":1}', '$.b'), JSON_VALUE('{"a":1}', '$.b' DEFAULT 'none' ON EMPTY), JSON_VALUE('{"a":[1]}', '$.a' DEFAULT 'e' ON ERROR), JSON_VALUE('{"a":[1]}', '$.a') FROM SYSIBM.SYSDUMMY1;
SELECT JSON_VALUE('{"a":1}', 'strict $.b') FROM SYSIBM.SYSDUMMY1;
SELECT JSON_VALUE('{"a":1}', 'strict $.b' ERROR ON EMPTY) FROM SYSIBM.SYSDUMMY1;
SELECT JSON_VALUE('{"a":1}', 'strict $.b' ERROR ON ERROR) FROM SYSIBM.SYSDUMMY1;
SELECT JSON_VALUE('{"a":"x"}', '$.a' RETURNING INTEGER ERROR ON ERROR) FROM SYSIBM.SYSDUMMY1;
SELECT JSON_VALUE('{"a":"x"}', '$.a' RETURNING INTEGER) FROM SYSIBM.SYSDUMMY1;
SELECT JSON_VALUE('not json', '$.a') FROM SYSIBM.SYSDUMMY1;
SELECT JSON_VALUE('not json', '$.a' ERROR ON ERROR) FROM SYSIBM.SYSDUMMY1;
SELECT JSON_VALUE('{"a":1}', 'bad path') FROM SYSIBM.SYSDUMMY1;
SELECT JSON_VALUE('[1,2,3]', '$[last]'), JSON_VALUE('[1,2,3]', 'lax $[5]'), JSON_VALUE('{"a":[{"b":1},{"b":2}]}', '$.a[1].b'), JSON_VALUE('{"a b":3}', '$."a b"'), JSON_VALUE('{"a":5}', 'lax $.a[0]') FROM SYSIBM.SYSDUMMY1;
SELECT JSON_QUERY('{"a":{"b":[10,20]}}', '$.a'), JSON_QUERY('{"a":{"b":[10,20]}}', '$.a.b'), JSON_QUERY('{"a":{"b":[10,20]}}', '$.a.b[0]'), JSON_QUERY('{"a":{"b":[10,20]}}', '$.a.b[0]' WITH WRAPPER), JSON_QUERY('{"a":{"b":[10,20]}}', '$.a.b[*]' WITH CONDITIONAL WRAPPER) FROM SYSIBM.SYSDUMMY1;
SELECT JSON_QUERY('{"a":"x"}', '$.a'), JSON_QUERY('{"a":"x"}', '$.a' KEEP QUOTES), JSON_QUERY('{"a":"x"}', '$.a' OMIT QUOTES), JSON_QUERY('{"a":1}', '$.b'), JSON_QUERY('{"a":1}', '$.b' EMPTY ARRAY ON EMPTY), JSON_QUERY('{"a":1}', '$.b' EMPTY OBJECT ON EMPTY) FROM SYSIBM.SYSDUMMY1;
SELECT JSON_QUERY('{"a" : [ 1 , {"b" :  2} ] }', '$') FROM SYSIBM.SYSDUMMY1;
SELECT JSON_QUERY('{"a":[1,2,3]}', '$.a[0 to 1]' WITH WRAPPER), JSON_QUERY('{"a":{"x":1,"y":2}}', '$.a.*' WITH WRAPPER) FROM SYSIBM.SYSDUMMY1;
SELECT JSON_EXISTS('{"a":1}', '$.a'), JSON_EXISTS('{"a":1}', '$.b'), JSON_EXISTS('x', '$.a'), JSON_EXISTS('{"a":1}', 'strict $.b' FALSE ON ERROR) FROM SYSIBM.SYSDUMMY1;
SELECT JSON_EXISTS('x', '$.a' ERROR ON ERROR) FROM SYSIBM.SYSDUMMY1;
SELECT CASE WHEN '{"a":1}' IS JSON THEN 1 ELSE 0 END, CASE WHEN 'x' IS JSON THEN 1 ELSE 0 END, CASE WHEN '[1]' IS JSON OBJECT THEN 1 ELSE 0 END, CASE WHEN '[1]' IS JSON ARRAY THEN 1 ELSE 0 END, CASE WHEN '1' IS JSON SCALAR THEN 1 ELSE 0 END, CASE WHEN '{"a":1,"a":2}' IS JSON WITH UNIQUE KEYS THEN 1 ELSE 0 END, CASE WHEN 'x' IS NOT JSON THEN 1 ELSE 0 END FROM SYSIBM.SYSDUMMY1;
SELECT HEX(JSON_TO_BSON('{"a":1,"b":"x","c":[true,null],"d":1.5,"e":12345678901}')) FROM SYSIBM.SYSDUMMY1;
SELECT BSON_TO_JSON(JSON_TO_BSON('{"a":1,"b":"x","c":[true,null],"d":1.5,"e":12345678901}')) FROM SYSIBM.SYSDUMMY1;
SELECT JSON_VALUE(JSON_TO_BSON('{"a":7}') FORMAT BSON, '$.a') FROM SYSIBM.SYSDUMMY1;
SELECT JSON_UPDATE('{"a":1,"b":2}', '$.a', 5), JSON_UPDATE('{"a":1}', '$.c', 'x'), JSON_UPDATE('{"a":1,"b":2}', '$.b') FROM SYSIBM.SYSDUMMY1;
SELECT JSON_UPDATE('{"a":1}', '$.a', '{"z":1}' FORMAT JSON) FROM SYSIBM.SYSDUMMY1;
CREATE TABLE {lib}.QSJS1 (K INTEGER, NAME VARCHAR(10), AMT DECIMAL(5, 2));
INSERT INTO {lib}.QSJS1 VALUES (1, 'a', 1.50), (2, 'b', NULL), (3, 'c', -2.00);
SELECT JSON_ARRAYAGG(NAME ORDER BY K DESC) FROM {lib}.QSJS1;
SELECT JSON_ARRAYAGG(AMT), JSON_ARRAYAGG(AMT NULL ON NULL) FROM {lib}.QSJS1;
SELECT JSON_OBJECTAGG(NAME VALUE AMT), JSON_OBJECTAGG(KEY NAME VALUE AMT ABSENT ON NULL) FROM {lib}.QSJS1;
SELECT JSON_OBJECT('k' VALUE K, 'n' VALUE NAME, 'a' VALUE AMT) FROM {lib}.QSJS1 ORDER BY K;
SELECT T.* FROM JSON_TABLE('{"r":[{"a":1,"b":"x"},{"a":2}]}', '$.r[*]' COLUMNS(A INTEGER PATH '$.a', B VARCHAR(5) PATH '$.b', N FOR ORDINALITY)) AS T;
SELECT T.* FROM JSON_TABLE('{"r":[{"a":1,"b":"x"},{"a":"q"}]}', 'lax $.r[*]' COLUMNS(A INTEGER PATH '$.a' DEFAULT -1 ON ERROR, B VARCHAR(5) PATH '$.b' DEFAULT 'none' ON EMPTY, J VARCHAR(20) FORMAT JSON PATH '$')) AS T;
DROP TABLE {lib}.QSJS1;
